    const oldMir=new Set((prev.ownMirrors||[]).map(m=>m.coord)),newMir=new Set((v.ownMirrors||[]).map(m=>m.coord));for(const c of newMir)if(!oldMir.has(c)){cellFx(c,'fx-summon','🪞','magic');heardMagic=true;}
    if((v.history?.[0]||'')!==(prev.history?.[0]||'')){panelFx(historyEl);const h=v.history?.[0]||'';if(h.includes('Espelho')&&h.includes('reflet')){for(const c of oldMir)if(!newMir.has(c))cellFx(c,'fx-reflect','↩','magic');heardReflect=true;}if(/Confronto|repelid/i.test(h))Audio.play('clash');}
